{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>{{BUSINESS_NAME}} — Restorative Sound Sessions</title>
  <meta name="description" content="Guided sound sessions and private offerings in {{CITY}}, {{STATE}} — intentional, warm, and attentive." />
  <link rel="stylesheet" href="assets/css/styles.css">
  <script defer src="assets/js/main.js"></script>
</head>
<body class="theme-earthy">
  <svg class="site-pattern" aria-hidden="true" focusable="false">
    <use href="assets/img/pattern.svg#pattern" />
  </svg>

  <header class="site-header">
    <div class="container">
      <a class="brand" href="/">{{BUSINESS_NAME}}</a>
      <nav class="main-nav" aria-label="Primary">
        <ul>
          <li><a href="/">Home</a></li>
          <li><a href="events.html">Events</a></li>
          <li><a href="private-sessions.html">Private Sessions</a></li>
          <li><a href="pricing.html">Offerings</a></li>
          <li><a href="about.html">About</a></li>
          <li><a href="faq.html">FAQ</a></li>
          <li><a href="book.html" class="cta">Book</a></li>
          <li><a href="contact.html">Contact</a></li>
        </ul>
      </nav>
      <button class="try-now" id="open-guided">Try a Moment</button>
    </div>
  </header>

  <main>

    <!-- HERO -->
    <section class="hero" data-reveal>
      <div class="container">
        <h1 class="eyebrow">A focused pause with tuned attention</h1>
        <p class="lead">Join small, attentive sound gatherings crafted to help you re-center and set a clear intention for the hours ahead.</p>
        <div class="hero-ctas">
          <a class="btn primary" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
          <button class="btn ghost" id="open-guided-2">Try a Moment</button>
        </div>
        <ul class="meta">
          <li>In-person + hybrid dates in {{CITY}}, {{STATE}}</li>
          <li><a href="tel:{{PHONE}}">Call: {{PHONE}}</a></li>
          <li><a href="mailto:{{EMAIL}}">{{EMAIL}}</a></li>
        </ul>
      </div>
    </section>

    <!-- BENEFITS (moved up for a different flow) -->
    <section class="benefits" data-reveal>
      <div class="container">
        <h2>What people notice</h2>
        <div class="grid">
          <div class="card">
            <h3>Clearer focus</h3>
            <p>Sound layers that support attention rather than distract—intended to help reframe the next part of your day.</p>
          </div>
          <div class="card">
            <h3>Softened tension</h3>
            <p>Low-frequency tones and long resonances that invite the body to ease without forcing rest.</p>
          </div>
          <div class="card">
            <h3>Grounded intention</h3>
            <p>Briefer ritual elements for setting an aim before returning to work or home life.</p>
          </div>
        </div>
      </div>
    </section>

    <!-- PROCESS -->
    <section class="process" data-reveal>
      <div class="container">
        <h2>How a session unfolds</h2>
        <ol class="steps">
          <li>
            <strong>Arrival & Settling</strong>
            <p>Comfortable mats and a quiet transition—5–10 minutes to adjust and set your posture.</p>
          </li>
          <li>
            <strong>Guided Intention</strong>
            <p>Brief soft spoken prompts to orient attention and create a simple intention for the time.</p>
          </li>
          <li>
            <strong>Sound Field</strong>
            <p>30–50 minutes of layered instruments and tones arranged to encourage measured attention and release.</p>
          </li>
          <li>
            <strong>Return</strong>
            <p>Gentle closure with notes and a short invitation to carry the intention forward.</p>
          </li>
        </ol>
      </div>
    </section>

    <!-- SOCIAL PROOF -->
    <section class="social-proof" data-reveal>
      <div class="container">
        <h2>From visitors</h2>
        <div class="testimonials">
          <blockquote>"I left steadier and quieter; I could feel the edges of the day soften."</blockquote>
          <blockquote>"A practical, warm pause—I could bring what I practiced into the next hour."</blockquote>
        </div>
      </div>
    </section>

    <!-- NEXT EVENT MODULE + MINI CALENDAR -->
    <section class="next-event" data-reveal>
      <div class="container">
        <h2>Upcoming — next session</h2>
        <div class="event-card">
          <div class="when">Sat • Feb 28 • 10:00–11:15</div>
          <div class="where">Gathering Room, {{CITY}}</div>
          <p class="desc">A focused sound assembly to re-center before the week turns. Small group; registration encouraged.</p>
          <a class="btn" href="events.html">See Events & RSVP</a>
        </div>
        <aside class="calendar-list">
          <h3>Future dates</h3>
          <ul>
            <li>Mar 6 — Evening session</li>
            <li>Mar 14 — Weekend slow-start</li>
            <li>Mar 21 — Midday pause</li>
          </ul>
        </aside>
      </div>
    </section>

    <!-- FAQ -->
    <section class="faq" data-reveal>
      <div class="container">
        <h2>Practical notes</h2>
        <details>
          <summary>How should I prepare?</summary>
          <p>Dress in comfortable layers. Bring a mat or use ours. Hydrate lightly. Arrival 10 minutes early recommended.</p>
        </details>
        <details>
          <summary>Are recordings available?</summary>
          <p>We occasionally share short takeaways after sessions; full recordings are not provided to preserve the live experience.</p>
        </details>
        <details>
          <summary>Contraindications</summary>
          <p>Not suitable for individuals with unmanaged epilepsy, certain inner ear conditions, or those who have medical instructions against exposure to prolonged tones. If you are pregnant, have implants, or medical devices, consult your physician before attending. If unsure, contact us at <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
        </details>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta" data-reveal>
      <div class="container">
        <h2>Ready to reserve a place?</h2>
        <p>Book a seat or schedule a private session for a more focused arrangement.</p>
        <div class="cta-actions">
          <a class="btn large primary" href="book.html">Reserve a Spot</a>
          <a class="btn large ghost" href="private-sessions.html">Private & Corporate</a>
        </div>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="container">
      <nav>
        <ul>
          <li><a href="/">Home</a></li>
          <li><a href="events.html">Events</a></li>
          <li><a href="contact.html">Contact</a></li>
        </ul>
      </nav>
      <p class="contact">Phone: <a href="tel:{{PHONE}}">{{PHONE}}</a> • <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      <p class="small">Contraindications: Please consult your healthcare provider if you have concerns about exposure to prolonged tones or vibration. We screen and advise with care for participants with medical devices or neurological conditions.</p>
      <p class="copyright">© <span id="year"></span> {{BUSINESS_NAME}}</p>
    </div>
  </footer>

  <!-- Guided "Try a Moment" Modal -->
  <div class="modal" id="guided-modal" aria-hidden="true" role="dialog" aria-labelledby="guided-title">
    <div class="modal-panel">
      <button class="modal-close" id="close-guided" aria-label="Close">✕</button>
      <h3 id="guided-title">A short arrival practice</h3>
      <div class="guided-steps" id="guided-steps">
        <section data-step="1" class="step">
          <h4>Breathing—two minutes</h4>
          <p>Settle into a comfortable seated position. Follow the circle to breathe in and out.</p>
          <div class="breath-circle" id="breath-circle" aria-hidden="true"></div>
          <div class="controls">
            <button id="start-breath" class="btn">Start</button>
            <div class="timer" id="breath-timer">02:00</div>
          </div>
        </section>
        <section data-step="2" class="step" hidden>
          <h4>Journaling—three minutes</h4>
          <p>Write a short note about what you want to carry forward. No need for perfect sentences.</p>
          <textarea id="journal" placeholder="A few words, intentions, or observations..."></textarea>
          <div class="controls">
            <button id="start-journal" class="btn">Start Timer</button>
            <div class="timer" id="journal-timer">03:00</div>
          </div>
        </section>
        <section data-step="3" class="step" hidden>
          <h4>Set an intention</h4>
          <p>Choose one brief phrase to carry into your next hour.</p>
          <div class="intentions">
            <button class="intent">Calm focus</button>
            <button class="intent">Kind attention</button>
            <button class="intent">Gentle energy</button>
          </div>
          <div class="controls">
            <button id="finish-guided" class="btn primary">Complete</button>
          </div>
        </section>
      </div>
    </div>
  </div>

</body>
</html>"} 
